import{_ as i,o as l,c as r,a2 as n,j as s,a}from"./chunks/framework.DxqK4cCD.js";const c=JSON.parse('{"title":"Morphing into Hybrid Attention Models","description":"FlashMorph 通过可微门控学习，高效自动地选择最优混合注意力层配置，平衡长上下文性能与计算效率。","frontmatter":{"title":"Morphing into Hybrid Attention Models","description":"FlashMorph 通过可微门控学习，高效自动地选择最优混合注意力层配置，平衡长上下文性能与计算效率。","date":"2026-07-06","arxivId":"2606.30562","domain":"自然语言处理","level":"进阶","tags":["混合注意力","层选择","可微架构搜索","长上下文","Transformer优化"],"originalUrl":"https://arxiv.org/abs/2606.30562","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-07-06/2606.30562.md"},"headers":[],"relativePath":"papers/daily/2026-07-06/2606.30562.md","filePath":"papers/daily/2026-07-06/2606.30562.md","lastUpdated":1786541753000}'),e={name:"papers/daily/2026-07-06/2606.30562.md"};function o(h,t,p,g,d,E){return l(),r("div",null,[...t[0]||(t[0]=[n("",15),s("ul",null,[s("li",null,[s("strong",null,"问题形式化"),a("：将混合注意力层选择定义为：在给定全注意力层预算 $K$ 的情况下，从 $L$ 层中选择一个子集 $S$（$|S| = K$），使得混合模型在长上下文任务上的性能最大化。这是一个组合优化问题，搜索空间为 $\\binom{L}{K}$，直接搜索代价高昂。")]),s("li",null,[s("strong",null,"可变形模型构建"),a("：对于原始Transformer的每一层 $l$，FlashMorph 将其替换为一个双分支模块。一个分支是原始的"),s("strong",null,"全注意力"),a("（Full Attention），另一个分支是转换后的"),s("strong",null,"线性注意力"),a("（Linear Attention，例如使用核方法或线性化近似）。每个分支前都有一个可学习的门控参数 $g_l \\in [0, 1]$。")]),s("li",null,[s("strong",null,"门控优化与正则化"),a("：冻结所有预训练权重，仅优化门控参数 ${g_1, g_2, ..., g_L}$。优化目标包含两部分：1）在合成检索数据上的损失函数（如交叉熵损失），鼓励模型正确检索；2）线性化正则化项 $\\mathcal{L}"),s("em",{task:""},"{reg} = \\sum_l (1 - g_l)$，鼓励门控值趋向于0（即选择线性注意力）。总损失为 $\\mathcal{L} = \\mathcal{L}"),a(" + \\lambda \\mathcal{L}_{reg}$，其中 $\\lambda$ 控制正则化强度。")]),s("li",null,[s("strong",null,"离散化与实例化"),a("：训练结束后，得到每个层的连续门控值。根据预设的预算 $K$，选择门控值最小的 $K$ 个层作为全注意力层（因为正则化鼓励了线性注意力，所以门控值小的层表示模型更依赖全注意力）。其余层则使用线性注意力。")]),s("li",null,[s("strong",null,"性能恢复"),a("：离散化后的混合模型会经历两个阶段的微调：1）"),s("strong",null,"Logits蒸馏"),a("：使用原始全注意力模型作为教师，对混合模型进行知识蒸馏，使其输出分布与教师模型对齐。2）"),s("strong",null,"长上下文微调"),a("：在长序列数据上对混合模型进行微调，以恢复其在长上下文任务上的性能。")])],-1),n("",6),s("ol",null,[s("li",null,[s("p",null,[s("strong",null,"门控融合输出"),a("：对于第 $l$ 层，其输出 $h_l$ 由全注意力输出 $h_l^{full}$ 和线性注意力输出 $h_l^{lin}$ 通过门控 $g_l$ 融合得到： $$h_l = (1 - g_l) \\cdot h_l^{full} + g_l \\cdot h_l^{lin}$$ 其中 $g_l \\in [0, 1]$。当 $g_l = 0$ 时，该层完全使用全注意力；当 $g_l = 1$ 时，完全使用线性注意力。")])]),s("li",null,[s("p",null,[s("strong",null,"总优化目标"),a("：门控优化的总损失函数由任务损失和线性化正则化项组成： $$\\mathcal{L} = \\mathcal{L}"),s("em",{l:"1"},"{task}({g_l}) + \\lambda \\sum"),a("^{L} (1 - g_l)$$ 其中 $\\mathcal{L}_{task}$ 是在合成检索数据上的交叉熵损失，$\\lambda$ 是正则化系数。正则化项鼓励 $g_l$ 趋向于 1（即使用线性注意力），从而迫使模型在必须使用全注意力时（即 $g_l$ 被迫变小）才保留它。")])]),s("li",null,[s("p",null,[s("strong",null,"离散化策略"),a("：在给定预算 $K$ 的情况下，选择全注意力层的集合 $S$ 为： $$S = \\arg \\min_{|S| = K} \\sum_{l \\in S} g_l$$ 即选择门控值 $g_l$ 最小的 $K$ 个层作为全注意力层。这直观上是因为这些层即使在线性注意力被强烈鼓励的情况下，仍然需要全注意力来完成任务。")])])],-1),n("",37)])])}const u=i(e,[["render",o]]);export{c as __pageData,u as default};
